{
  "headline": "Insulin glulisine is not on FDA's shortage list as of 2026-10-21; FDA records show a registered plant for Baxter Healthcare Corporation classified OAI on 2026-04-02 and a Warning Letter on 2026-09-29",
  "headline_cites": ["D16", "E35", "E32", "E33"],
  "sentences": [
    {
      "text": "FDA's drug shortage list does not include insulin glulisine as of 2026-10-21.",
      "cites": ["D16"]
    },
    {
      "text": "A registered plant for Baxter Healthcare Corporation (FEI 1416980) was classified OAI after an inspection that ended 2026-04-02.",
      "cites": ["E35", "E32"]
    },
    {
      "text": "FDA issued a Warning Letter to Baxter Healthcare Corporation on 2026-09-29 for the same plant.",
      "cites": ["E33"]
    },
    {
      "text": "Sanofi-Aventis Deutschland GmbH (FEI 3003195501) has a registered plant with a most recent VAI inspection ending 2022-03-25 and a prior OAI inspection ending 2010-09-16.",
      "cites": ["E25", "E23", "E17"]
    },
    {
      "text": "Genzyme Corporation (FEI 3009389940) is a registered plant with a NAI inspection ending 2016-08-18.",
      "cites": ["E37", "E36"]
    },
    {
      "text": "A-S Medication Solutions (FEI 1450743) is a registered plant with a VAI inspection ending 2026-08-12.",
      "cites": ["E44", "E42"]
    },
    {
      "text": "Corvale Lakeside holds 19 syringes of insulin glulisine 3 mL at 3.6 per day for 5.3 days on hand; Corvale General holds 175 syringes at 11.7 per day for 15 days on hand and can spare 11 syringes while keeping two weeks, raising Lakeside to 8 days.",
      "cites": ["D2", "D1", "D17"]
    }
  ]
}
